function initPersistentWheelList(){const textarea = document.getElementById("wheel-input");const key = textarea.dataset.storageKey;let saved;try{saved = localStorage.getItem(key);}catch{saved = null;}if (saved){textarea.value = saved;redrawWheelFromInput();}textarea.addEventListener("input", () =>{try{localStorage.setItem(key, textarea.value);}catch{}});}document.addEventListener("DOMContentLoaded", initPersistentWheelList);